const std = @import("std");

fn hanoi(n: u32, from: u8, to: u8, aux: u8) void {
    if (n == 0) return;
    hanoi(n - 1, from, aux, to);
    std.debug.print("Move disk {} from {} to {}\n", .{n, from, to});
    hanoi(n - 1, aux, to, from);
}

pub fn main() !void {
    hanoi(3, 'A', 'C', 'B');
}
